import 'package:flutter/material.dart'; import '../../../core/network/api_endpoints.dart'; import '../../../core/network/dio_client.dart'; import '../../../shared/widgets/app_card.dart';
class PlatformTokensPage extends StatefulWidget{const PlatformTokensPage({super.key});@override State<PlatformTokensPage> createState()=>_S();}
class _S extends State<PlatformTokensPage>{List<Map<String,dynamic>> items=[];bool loading=true;@override void initState(){super.initState();load();}Future<void> load()async{final r=await DioClient.instance.dio.get(ApiEndpoints.platformTokens);final d=r.data is Map?r.data['data']:null;if(mounted)setState((){items=d is List?d.whereType<Map>().map((e)=>Map<String,dynamic>.from(e)).toList():[];loading=false;});}Future<void> toggle(Map x)async{final id=(x['id']as num).toInt();await DioClient.instance.dio.put(x['enabled']==true?ApiEndpoints.platformTokenDisable(id):ApiEndpoints.platformTokenEnable(id));await load();}Future<void> remove(int id)async{await DioClient.instance.dio.delete(ApiEndpoints.platformTokenById(id));await load();}@override Widget build(BuildContext c)=>Scaffold(backgroundColor:Colors.transparent,appBar:AppBar(title:const Text('平台令牌')),body:loading?const Center(child:CircularProgressIndicator()):ListView(padding:const EdgeInsets.all(20),children:[for(final x in items)AppCard(margin:const EdgeInsets.only(bottom:8),child:ListTile(title:Text(x['name']?.toString()??''),subtitle:Text('${x['platform_name']??''} · ${x['remarks']??''}'),leading:Switch(value:x['enabled']==true,onChanged:(_)=>toggle(x)),trailing:IconButton(icon:const Icon(Icons.delete_outline),onPressed:()=>remove((x['id']as num).toInt()))))]));}
